PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ssn-system: <http://example.org/ssn-system#>

SELECT ?device ?operatingProperty ?performanceImpact
WHERE {
  ?device rdf:type ssn:System .
  ?device ssn:hasOperatingProperty ?operatingProperty .
  ?operatingProperty rdf:type ssn-system:OperatingProperty .
  OPTIONAL {
    ?operatingProperty ssn:hasPerformanceImpact ?performanceImpact .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX saref4city: <https://w3id.org/def/saref4city#>

SELECT ?property ?propertyType
WHERE {
  saref4city:City rdfs:subClassOf* ?superClass .
  ?superClass rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty ?property ;
    owl:someValuesFrom ?propertyType
  ].
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX ssn: <http://www.w3.org/ns/ssn/>
PREFIX ssn-system: <http://example.org/ssn/system/>

SELECT ?definition ?difference
WHERE {
  ssn-system:SurvivalProperty rdfs:isDefinedBy ?definition .
  FILTER NOT EXISTS {
    ssn:Property rdfs:isDefinedBy ?otherDefinition .
    FILTER(?otherDefinition != ?definition)
  }
  OPTIONAL {
    ssn-system:SurvivalProperty rdfs:subClassOf ?superClass .
    ?superClass rdfs:label ?difference
  }
}

