PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX ssn: <http://www.w3.org/ns/ssn/>

SELECT ?definition ?usage
WHERE {
  sosa:ActuatableProperty rdfs:isDefinedBy ?definition .
  OPTIONAL {
    ?subject sosa:hasActuation ?actuation ;
             sosa:actsOnProperty sosa:ActuatableProperty .
    ?actuation sosa:madeByActuator ?actuator .
    BIND(CONCAT("Used by ", STR(?actuator), " to act on ", STR(?subject)) AS ?usage)
  }
}

