PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX iot: <http://iot.linkeddata.es/def/core#>

SELECT ?contributor ?importedOntology
WHERE {
  {
    # Find contributors and creators of the core ontology
    iot: dcterms:creator ?contributor .
  }
  UNION
  {
    iot: dcterms:contributor ?contributor .
  }
  # Find ontologies imported by the core ontology
  iot: owl:imports ?importedOntology .
  # Check if the same contributor or creator has contributed to the imported ontology
  ?importedOntology (dcterms:creator | dcterms:contributor) ?contributor .
}

