SELECT ?organization
WHERE {
  ?organization org:hasPartnershipWith ?partner .
  {
    SELECT ?organization (COUNT(DISTINCT ?partner) AS ?count)
    WHERE {
      ?organization org:hasPartnershipWith ?partner .
    }
    GROUP BY ?organization
    HAVING (COUNT(DISTINCT ?partner) > 3)
  }
}

