PREFIX org: <http://www.w3.org/ns/org#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?org
WHERE {
  ?org a org:Organization ;
       :hasPartnershipWith ?partner .
  FILTER NOT EXISTS {
    ?org :hasPartnershipWith ?otherPartner .
    FILTER (?otherPartner != ?org && ?otherPartner != ?partner)
  }
  FILTER NOT EXISTS {
    ?partner :hasPartnershipWith ?otherOrg .
    FILTER (?otherOrg != ?org && ?otherOrg != ?partner)
  }
}
